def parse_wkt_point(wkt_string):
    """Parse WKT POINT format and return (longitude, latitude)"""
    if not wkt_string:
        return None, None

    # Handle POINT(longitude latitude) format
    match = re.match(r'POINT\s*\(\s*([-\d.]+)\s+([-\d.]+)\s*\)', wkt_string)
    if match:
        longitude = float(match.group(1))
        latitude = float(match.group(2))
